page_settings.custom_css:
/* Aluminis Albera - acabado fino (skills: make-interfaces-feel-better, typography, viewports, reduced-motion) */
body { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; background: #0c0c0d; }
.elementor-heading-title { text-wrap: balance; }
.elementor-widget-text-editor p, .elementor-icon-box-description, .elementor-icon-list-text { text-wrap: pretty; max-width: 70ch; }
.elementor-widget-text-editor, .elementor-widget-icon-box { max-width: 100%; }
.elementor-widget-image img { outline: 1px solid rgba(255,255,255,.08); outline-offset: -1px; object-fit: cover; }
.elementor-location-header img, .elementor-location-footer img { outline: 0; object-fit: contain; }
.elementor-widget-image a { display: block; overflow: hidden; }
.elementor-widget-image a img { transition: transform .45s cubic-bezier(.2,.8,.2,1); }
.elementor-widget-image a:hover img { transform: scale(1.04); }
.elementor-button { min-height: 44px; transition: filter .2s ease, transform .15s ease, background-color .2s ease, border-color .2s ease; }
.elementor-button:hover { filter: brightness(1.12); }
.elementor-button:active { transform: scale(.97); }
.elementor-icon-box-title a, .elementor-heading-title a { transition: color .2s ease; }
.elementor-heading-title a:hover { color: #e4152d; }
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible, .elementor-button:focus-visible { outline: 2px solid #fff; outline-offset: 3px; border-radius: 2px; }
.elementor-nav-menu a.elementor-item { min-height: 44px; display: inline-flex; align-items: center; white-space: nowrap; }
.elementor-accordion .elementor-tab-title { min-height: 44px; }
.elementor-column > .elementor-widget-wrap { min-width: 0; }
@media (max-width: 767px) { .elementor-widget-text-editor p, .elementor-icon-box-description { font-size: 15px; } .elementor-widget-image img { height: auto; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; scroll-behavior: auto !important; } .elementor-widget-image a:hover img { transform: none; } }
